local Configuration = {}
Configuration.__index = Configuration
function Configuration.new(seed) return setmetatable({ values = seed or {}, changed = {} }, Configuration) end
function Configuration:Set(key, value) self.values[key] = value; for _, callback in ipairs(self.changed[key] or {}) do task.spawn(callback, value) end end
function Configuration:Get(key, fallback) local value = self.values[key]; return value == nil and fallback or value end
function Configuration:OnChanged(key, callback) self.changed[key] = self.changed[key] or {}; table.insert(self.changed[key], callback) end
return Configuration
end

__factories["Systems/DeviceManager"] = function()
local UserInputService = game:GetService("UserInputService")
local DeviceManager = {}
function DeviceManager:IsTouch() return UserInputService.TouchEnabled end
function DeviceManager:IsMobile() return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled end
function DeviceManager:GetViewport() return workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.zero end
return DeviceManager
end

__factories["Systems/Notifications"] = function()
local UIUtil = __require("Core/UIUtil")
local Notifications = {}
Notifications.__index = Notifications
function Notifications.new(window)
    local holder = Instance.new("Frame", window.gui); holder.Name = "Notifications"; holder.BackgroundTransparency = 1; holder.Position = UDim2.new(1, -285, 0, 16); holder.Size = UDim2.fromOffset(265, 0); holder.AutomaticSize = Enum.AutomaticSize.Y
    local layout = Instance.new("UIListLayout", holder); layout.Padding = UDim.new(0, 7)
    return setmetatable({ window = window, holder = holder }, Notifications)
end
function Notifications:Show(options)
    local card = Instance.new("Frame", self.holder); card.Size = UDim2.new(1, 0, 0, 68); card.BackgroundColor3 = self.window.theme.Surface; UIUtil.corner(card, 8); UIUtil.stroke(card, self.window.theme.Border)
    local title = UIUtil.label(card, options.Title or "NEXUS UI", 14, self.window.theme.Text); title.Position = UDim2.fromOffset(12, 9); title.Size = UDim2.new(1, -24, 0, 20)
    local content = UIUtil.label(card, options.Content or "", 11, self.window.theme.Muted); content.Position = UDim2.fromOffset(12, 33); content.Size = UDim2.new(1, -24, 0, 20)
    task.delay(options.Duration or 4, function() if card.Parent then card:Destroy() end end)
    return card
end
return Notifications
end

__factories["Systems/Search"] = function()
local Search = {}
function Search.Filter(items, query, getter)
    local result = {}; query = string.lower(query or "")
    for _, item in ipairs(items) do if string.find(string.lower(getter and getter(item) or tostring(item)), query, 1, true) then table.insert(result, item) end end
    return result
end
return Search
end

__factories["Themes/Adaptive"] = function()
local dark = __require("Themes/NEXUSDark")
local UserInputService = game:GetService("UserInputService")
local Adaptive = table.clone(dark)
Adaptive.Name = "Adaptive"
function Adaptive:Resolve()
    local resolved = table.clone(self)
    if UserInputService.TouchEnabled then
        resolved.Surface = Color3.fromRGB(22, 26, 40)
        resolved.SurfaceHover = Color3.fromRGB(35, 42, 63)
    end
    return resolved
end
return Adaptive
end

